script:
country_event = {
	id = origin.4000
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		has_origin = origin_payback
	}

	immediate = {
		low_tech_start_add_research_options_effect = yes

		capital_scope = {
			solar_system = {
				set_star_flag = payback_system
			}

			# Dig site + ambient objects, for decoration
			owner = {
				set_country_flag = payback_origin_arcsite_owner@prev.planet
			}

			set_carrier_flag = payback_site_planet
			set_carrier_flag = has_orbital_debris
			create_archaeological_site = payback_digsite
			create_ambient_object = {
				type = "payback_site_ship_object"
				use_3d_location = yes
				entity_offset_height = 10
				location = this
			}
			create_ambient_object = {
				type = "ancient_battlefield_02_object"
				use_3d_location = yes
				entity_offset_height = 0
				location = this
			}
			while = {
				count = 5
				create_ambient_object = {
					type = "small_debris_object"
					use_3d_location = yes
					entity_offset_height = { min = 10 max = -10 }
					location = this
				}
				last_created_ambient_object = {
					set_location = {
						target = prev
						distance = 200
						angle = random
					}
				}
			}
			while = {
				count = 5
				create_ambient_object = {
					type = "abandoned_ship_2_object"
					use_3d_location = no
					entity_offset_height = { min = 20 max = -20 }
					location = this
				}
				last_created_ambient_object = {
					set_location = {
						target = prev
						distance = 150
						angle = random
					}
				}
			}
		}
	}
}

